import csv, collections, os, statistics, sys
# stockfish-tests.tsv sits next to this script; it is regenerated by scripts/parse-stockfish-commits.py
T = os.path.join(os.path.dirname(os.path.abspath(__file__)), "stockfish-tests.tsv")
rows = list(csv.DictReader(open(T), delimiter="\t"))
sprt = [r for r in rows if r["sprt_elo0"] != ""]
# bounds by model and year range, top per (model, tc, nonreg)
c = collections.Counter()
yrs = collections.defaultdict(list)
for r in sprt:
    k = (r["elo_model"], r["tc"], r["nonreg"], r["sprt_elo0"], r["sprt_elo1"])
    c[k] += 1
    yrs[k].append(r["date"])
print("model tc nonreg elo0 elo1 count first last")
for k, n in c.most_common(45):
    print(*k, n, min(yrs[k]), max(yrs[k]))
# median games for passed gainer tests by era/tc
print()
eras = [("2013-2019", "2013", "2019-99"), ("2020-2021-04", "2020", "2021-04-24"), ("2021-05-2023", "2021-04-25", "2023-99"), ("2024-2026", "2024", "2026-99")]
for name, a, b in eras:
    for tc in ["STC", "LTC", "VLTC", "VVLTC"]:
        for nr in ["False", "True"]:
            g = [int(r["games"]) for r in sprt if a <= r["date"] <= b and r["tc"] == tc and r["passed"] == "True" and r["nonreg"] == nr and r["games"]]
            if len(g) >= 5:
                print(name, tc, "nonreg" if nr == "True" else "gainer", "n=%d" % len(g), "median_games=%d" % statistics.median(g), "p90=%d" % sorted(g)[int(0.9 * len(g))])
# pentanomial share by year
print()
by = collections.defaultdict(lambda: [0, 0])
for r in rows:
    y = r["date"][:4]
    by[y][0] += 1
    by[y][1] += r["ptnml"] != ""
print(" ".join("%s:%d/%d" % (y, v[1], v[0]) for y, v in sorted(by.items())))
# draw rate by era for LTC passed gainer
print()
for name, a, b in eras:
    for tc in ["STC", "LTC"]:
        ds = [int(r["d"]) / int(r["games"]) for r in sprt if a <= r["date"] <= b and r["tc"] == tc and r["games"] and int(r["games"]) > 0]
        if ds:
            print(name, tc, "median draw rate %.3f" % statistics.median(ds), "n=%d" % len(ds))
# threads in tests
print()
print(collections.Counter(r["threads"] for r in rows).most_common(8))
# tc label distribution
print(collections.Counter(r["tc"] for r in rows).most_common(12))
